// Shipaton/judging only: marks the Android `release` build debuggable so
// RevenueCat's SDK accepts the Test Store API key in a sideloaded APK (it
// refuses test keys whenever android:debuggable is false). Lives here rather
// than in android/app/build.gradle because android/ is generated by prebuild
// and gitignored. Remove this plugin before any real Play Store release.
const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = 'debuggable true // with-debuggable-release';

module.exports = function withDebuggableRelease(config) {
  return withAppBuildGradle(config, (cfg) => {
    if (cfg.modResults.contents.includes(MARKER)) return cfg;
    cfg.modResults.contents = cfg.modResults.contents.replace(
      /(buildTypes\s*\{[\s\S]*?release\s*\{)/,
      `$1\n            ${MARKER}`,
    );
    return cfg;
  });
};
